# Split utilities for temporal train/test split
"""
Utility functions to split the feature dataset into training and test sets
while preserving chronological order. The split is based on a cutoff date
or a proportion of the most recent weeks.
"""

import pandas as pd
from datetime import datetime


def load_features(csv_path: str) -> pd.DataFrame:
    """Load the feature CSV generated by the pipeline.

    Parameters
    ----------
    csv_path: str
        Path to the ``pb_arboviroses_features.csv`` file.

    Returns
    -------
    pd.DataFrame
        DataFrame with a parsed ``data_inicio_se`` column as ``datetime``.
    """
    df = pd.read_csv(csv_path, parse_dates=["data_inicio_se"], dayfirst=False)
    return df


def temporal_train_test_split(
    df: pd.DataFrame,
    test_weeks: int = 12,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Split the DataFrame into train and test sets using the most recent weeks.

    Parameters
    ----------
    df: pd.DataFrame
        Feature DataFrame sorted by ``data_inicio_se``.
    test_weeks: int, default 12
        Number of weeks to reserve for testing.

    Returns
    -------
    (train_df, test_df): tuple of DataFrames
    """
    if "data_inicio_se" not in df.columns:
        raise ValueError("Column 'data_inicio_se' not found in DataFrame")
    df = df.sort_values("data_inicio_se").reset_index(drop=True)
    # Determine cutoff date
    max_date = df["data_inicio_se"].max()
    cutoff_date = max_date - pd.Timedelta(weeks=test_weeks)
    train_df = df[df["data_inicio_se"] <= cutoff_date]
    test_df = df[df["data_inicio_se"] > cutoff_date]
    return train_df, test_df

if __name__ == "__main__":
    # Simple CLI for quick verification
    import argparse
    parser = argparse.ArgumentParser(description="Temporal split of feature dataset")
    parser.add_argument("csv_path", help="Path to feature CSV")
    parser.add_argument("--test-weeks", type=int, default=12, help="Weeks for test set")
    args = parser.parse_args()
    df = load_features(args.csv_path)
    train, test = temporal_train_test_split(df, args.test_weeks)
    print(f"Train rows: {len(train)}, Test rows: {len(test)}")
